import {ownRecord,denseValues} from './state-validation.mjs';
export const chemistryLabActivity={id:'chemistry-lab',stage:'7y',key:'7y:chemistry-lab',area:'Ciencia',type:'digital',label:'9–12 años · modelo acompañado',kind:'interactive',title:'Química · Construye un modelo de mezcla',unit:'Identidades que se conservan',copy:'Construye dos modelos de partículas y compara qué cambia y qué permanece.',goal:'Distinguir una sustancia y una mezcla en un modelo limitado, usando identidades y cantidades como evidencia.',duration:'Dos modelos a tu ritmo',support:'Lectura acompañada si hace falta; teclado o botones, sin arrastrar',transfer:'En papel, dibuja dos modelos con símbolos A y B. Explica qué representan. No uses sustancias reales.'};
export const chemistryPredictions={single:'Una sola sustancia',mixture:'Una mezcla de sustancias'};
export const chemistryReasons={identities:'Me fijo en cuántas sustancias distintas están representadas.',position:'Decido por la posición o la separación entre fichas.',total:'Decido solo por el número total de fichas.'};
export const newChemistryLab=()=>({open:true,page:'guide',cells:Array(6).fill(null),tool:'A',undo:null,prediction:null,tested:false,original:null,reason:null,reviewed:false,hint:false});
const cells=v=>denseValues(v,[null,'A','B'],6,true);
export function chemistryResult(raw){const c=cells(raw),a=c.filter(x=>x==='A').length,b=c.filter(x=>x==='B').length;return {a,b,total:a+b,kinds:Number(a>0)+Number(b>0),classification:a&&b?'mixture':a||b?'single':'empty'};}
const choice=(v,options)=>v===null||typeof v==='string'&&Object.hasOwn(options,v);
function record(v){ownRecord(v,['cells','prediction']);const c=cells(v.cells);if(!chemistryResult(c).total||!choice(v.prediction,chemistryPredictions)||v.prediction===null)throw Error('Invalid chemistry record');return {cells:c,prediction:v.prediction};}
export function validateChemistryLab(s){ownRecord(s,['open','page','cells','tool','undo','prediction','tested','original','reason','reviewed','hint']);const c=cells(s.cells),undo=s.undo===null?null:cells(s.undo),original=s.original===null?null:record(s.original);if(typeof s.open!=='boolean'||!['guide','build','revise','close'].includes(s.page)||![null,'A','B'].includes(s.tool)||![s.tested,s.reviewed,s.hint].every(x=>typeof x==='boolean')||!choice(s.prediction,chemistryPredictions)||!choice(s.reason,chemistryReasons))throw Error('Invalid chemistry state');if(s.tested&&(!chemistryResult(c).total||!s.prediction||!original)||s.reviewed&&(!s.tested||!s.reason)||s.reason&&!s.tested||s.page==='guide'&&(c.some(Boolean)||s.prediction||s.tested||original||s.reason||s.reviewed||s.hint||undo)||s.page==='build'&&(s.reason||s.reviewed)||['revise','close'].includes(s.page)&&!original||s.page==='close'&&(!s.tested||!s.reviewed))throw Error('Inconsistent chemistry state');return {...s,cells:c,undo,original};}
export function placeChemistry(s,index){if(!['build','revise'].includes(s.page)||!Number.isInteger(index)||index<0||index>5||s.cells[index]===s.tool)return false;s.undo=cells(s.cells);s.cells[index]=s.tool;s.prediction=null;s.tested=false;s.reason=null;s.reviewed=false;return true;}
export function testChemistry(s){if(!['build','revise'].includes(s.page)||!s.prediction||!chemistryResult(s.cells).total)return false;s.tested=true;if(!s.original)s.original={cells:cells(s.cells),prediction:s.prediction};return true;}
export function chemistryFeedback(s){const r=chemistryResult(s.cells);if(!s.tested)return 'Resultado pendiente: construye, anticipa y comprueba.';return `${r.a} ${r.a===1?'ficha':'fichas'} A y ${r.b} ${r.b===1?'ficha':'fichas'} B: ${r.kinds} ${r.kinds===1?'sustancia representada':'sustancias representadas'}. ${chemistryPredictions[r.classification]}. ${s.prediction===r.classification?'Coincide con tu predicción.':'Tu predicción era distinta; puedes revisarla sin penalización.'} Cambiar de casilla una ficha no cambia su identidad.`;}
export function undoChemistry(s){if(!s.undo||!['build','revise'].includes(s.page))return false;s.cells=cells(s.undo);s.undo=null;s.prediction=null;s.tested=false;s.reason=null;s.reviewed=false;return true;}
const button=(id,text,disabled=false)=>`<button type="button" class="action secondary" id="${id}" ${disabled?'disabled':''}>${text}</button>`;
const icon=x=>x===null?'<span aria-hidden="true">＋</span>':`<svg viewBox="0 0 70 50" width="70" height="50" aria-hidden="true">${x==='A'?'<circle cx="35" cy="25" r="21" fill="#dbe8ab" stroke="#235646" stroke-width="2"/>':'<rect x="14" y="4" width="42" height="42" rx="8" fill="#f5dfca" stroke="#813e20" stroke-width="2"/>'}<text x="35" y="32" text-anchor="middle" font-size="22" fill="#203c37">${x}</text></svg>`;
const board=(c,editable)=>`<div class="compose-board">${c.map((x,i)=>editable?`<button type="button" class="compose-cell" data-chemistry-cell="${i}" aria-label="Casilla ${i+1}: ${x?'sustancia '+x:'vacía'}">${icon(x)}<span>${x?'Sustancia '+x:'Vacía'}</span></button>`:`<div class="compose-cell">${icon(x)}<span>${x?'Sustancia '+x:'Vacía'}</span></div>`).join('')}</div>`;
export function renderChemistryLab(root,state,{back,finish}={}){const s=state.chemistryLab??=newChemistryLab();const r=chemistryResult(s.cells);const redraw=sel=>{renderChemistryLab(root,state,{back,finish});root.querySelector(sel)?.focus();};let content='';
if(s.page==='guide')content=`<p>Construye un modelo con hasta seis fichas. Cada A representa una partícula de una sustancia imaginaria A; cada B, una de otra sustancia B. Conservamos esas identidades: aquí no hay reacciones.</p><p>Anticipa si representas una sustancia o una mezcla, comprueba y crea otra versión. No hace falta acertar a la primera.</p>${button('chemistry-start','Construir mi modelo')}`;
else content=`${s.page==='revise'?'<p>Tu primer modelo comprobado queda guardado. Prueba otra cantidad o distribución, o conserva tu modelo. Observa si cambia el número de sustancias distintas.</p>':''}${s.page!=='close'?`<fieldset><legend>1. Elige una ficha y pulsa una casilla</legend><div class="controls">${['A','B',null].map(x=>`<button type="button" class="action secondary" data-chemistry-tool="${x??'empty'}" aria-pressed="${s.tool===x}">${x?'Ficha de sustancia '+x:'Vaciar una casilla'}</button>`).join('')}</div>${button('chemistry-undo','Deshacer el último cambio',!s.undo)}<p>Tab y Enter o Espacio. Las casillas son lugares del dibujo, no un recipiente real.</p></fieldset>`:''}<div class="compose-versions ${s.original?'':'compose-single'}">${s.original?`<article><h5>Primer modelo comprobado</h5>${board(s.original.cells,false)}<p>Predicción: ${chemistryPredictions[s.original.prediction]}. Clasificación del modelo: ${chemistryPredictions[chemistryResult(s.original.cells).classification]}.</p></article>`:''}<article><h5>${s.page==='close'?'Modelo al cerrar':'Tu modelo editable'}</h5>${board(s.cells,s.page!=='close')}</article></div>${s.page!=='close'?`<fieldset><legend>2. Antes de comprobar, anticipa</legend><div class="controls">${Object.entries(chemistryPredictions).map(([id,label])=>`<button type="button" class="action secondary" data-chemistry-prediction="${id}" aria-pressed="${s.prediction===id}" ${s.tested?'disabled':''}>${label}</button>`).join('')}</div></fieldset>${button('chemistry-test','Comprobar el modelo',!r.total||!s.prediction)}${!r.total?'<p>Añade al menos una ficha. Un dibujo vacío no representa aquí una muestra de sustancia.</p>':''}`:''}<p id="chemistry-feedback" role="status" tabindex="-1">${chemistryFeedback(s)}</p>${s.page==='build'?button('chemistry-next','Construir una alternativa',!s.tested):''}${s.page==='revise'&&s.tested?`<fieldset><legend>3. Explica tu clasificación</legend><div class="controls">${Object.entries(chemistryReasons).map(([id,label])=>`<button type="button" class="action secondary" data-chemistry-reason="${id}" aria-pressed="${s.reason===id}">${label}</button>`).join('')}</div></fieldset>${button('chemistry-explain','Revisar mi explicación',!s.reason)}`:''}${s.reviewed?`<p id="chemistry-explanation" role="status" tabindex="-1">${s.reason==='identities'?'La relación es válida: una identidad representa una sustancia; A y B juntas representan una mezcla en este modelo.':'La explicación necesita revisión: cantidad y posición no bastan. Cuenta las sustancias distintas; una A y una B ya representan una mezcla.'} No se deducen color real, toxicidad ni otras propiedades de estas fichas.</p>`:''}${s.page==='revise'?button('chemistry-close','Comparar y cerrar',!s.reviewed):''}${s.page==='close'?`<p>El primer registro contiene ${chemistryResult(s.original.cells).total} ${chemistryResult(s.original.cells).total===1?'ficha':'fichas'} y el último, ${r.total}. Comparar estos recuentos no mide masa: no asignamos masas a A o B.</p><p>Fuera de pantalla: dibuja dos modelos con A y B. Explica qué representan y qué no sabemos de ellos. Solo papel; no uses ni mezcles sustancias reales.</p><div class="controls">${button('chemistry-revise','Revisar mi modelo')}${button('chemistry-finish','Terminar por hoy')}</div>`:''}`;
root.innerHTML=`<section class="chemistry-lab composition" aria-labelledby="chemistry-title"><p class="eyebrow">Química · 9–12 años · modelo acompañado</p><h4 id="chemistry-title" tabindex="-1">Identidades que se conservan</h4><p class="notice">Representación idealizada, no experimento. A y B son etiquetas inventadas, no símbolos de elementos. Las formas y colores ayudan a distinguirlas; no son su aspecto real.</p>${content}${['build','revise'].includes(s.page)?`<div class="controls">${button('chemistry-hint','Una pista para comparar')}</div><p id="chemistry-hint-text" role="status" tabindex="-1">${s.hint?'Prueba dos A y después añade una B. ¿Cambió solo el total o también las sustancias presentes? Mover una A no la convierte en B.':''}</p>`:''}<details><summary>Qué muestra y qué no muestra</summary><p>Solo representamos identidades y número de fichas. En este modelo, cada sustancia tiene un único tipo de partícula. No sirve para describir todas las sustancias, sus enlaces, movimiento, tamaño, masa, temperatura o propiedades. Las partículas reales no quedan quietas en casillas.</p><p>No hay formación de sustancias nuevas. No usamos «se puede deshacer» como prueba de que un cambio sea físico. No hagas pruebas con calor, productos, mezclas o degustación.</p></details><p class="quiet">Puedes pausar o terminar arriba. Revisar no resta puntos y este taller no certifica conocimientos.</p>${back?button('chemistry-back','Volver a los ejemplos'):''}</section>`;
const on=(id,fn)=>{root.querySelector('#'+id)?.addEventListener('click',fn);};on('chemistry-undo',()=>{undoChemistry(s);redraw('[data-chemistry-cell]');});on('chemistry-start',()=>{s.page='build';redraw('#chemistry-title');});root.querySelectorAll('[data-chemistry-tool]').forEach(b=>b.onclick=()=>{s.tool=b.dataset.chemistryTool==='empty'?null:b.dataset.chemistryTool;redraw(`[data-chemistry-tool="${b.dataset.chemistryTool}"]`);});root.querySelectorAll('[data-chemistry-cell]').forEach(b=>b.onclick=()=>{placeChemistry(s,Number(b.dataset.chemistryCell));redraw(`[data-chemistry-cell="${b.dataset.chemistryCell}"]`);});root.querySelectorAll('[data-chemistry-prediction]').forEach(b=>b.onclick=()=>{s.prediction=b.dataset.chemistryPrediction;redraw(`[data-chemistry-prediction="${s.prediction}"]`);});on('chemistry-test',()=>{testChemistry(s);redraw('#chemistry-feedback');});on('chemistry-next',()=>{s.page='revise';s.hint=false;redraw('#chemistry-title');});root.querySelectorAll('[data-chemistry-reason]').forEach(b=>b.onclick=()=>{s.reason=b.dataset.chemistryReason;s.reviewed=false;redraw(`[data-chemistry-reason="${s.reason}"]`);});on('chemistry-explain',()=>{s.reviewed=true;redraw('#chemistry-explanation');});on('chemistry-close',()=>{s.page='close';redraw('#chemistry-title');});on('chemistry-revise',()=>{s.page='revise';redraw('#chemistry-title');});on('chemistry-hint',()=>{s.hint=true;redraw('#chemistry-hint-text');});on('chemistry-finish',()=>finish?.());on('chemistry-back',()=>{s.open=false;back?.();});}
